#!/usr/bin/env python3
"""NLI threshold continuous curve: sweep BT across 11 NLI thresholds to prove robustness."""

import json
import os
import sys
from pathlib import Path

import numpy as np

try:
    import choix
except ImportError:
    sys.exit("choix not installed")


THRESHOLDS = [0.50, 0.55, 0.60, 0.65, 0.70, 0.75, 0.80, 0.85, 0.90, 0.95, 0.98]
N_BOOTSTRAP = 10000
SEED = 42


def load_jsonl(path):
    records = []
    with open(path, "r") as f:
        for line in f:
            line = line.strip()
            if line:
                records.append(json.loads(line))
    return records


def bt_probability(comparisons, n_players=2):
    """Compute BT probability for player 0 from list of (winner, loser) tuples."""
    if len(comparisons) < 2:
        return None
    try:
        params = choix.ilsr_pairwise(n_players, comparisons, alpha=0.01)
        p = np.exp(params[0]) / (np.exp(params[0]) + np.exp(params[1]))
        return float(p)
    except Exception:
        return None


def pairs_to_comparisons(pairs, style_pref_field):
    """Convert pair records to (winner, loser) tuples. Player 0 = style_A, 1 = style_B."""
    comps = []
    for p in pairs:
        t1 = p.get(f"trial1_prefers_{style_pref_field}")
        t2 = p.get(f"trial2_prefers_{style_pref_field}")
        if t1 is True:
            comps.append((0, 1))
        elif t1 is False:
            comps.append((1, 0))
        if t2 is True:
            comps.append((0, 1))
        elif t2 is False:
            comps.append((1, 0))
    return comps


def bootstrap_bt(pairs, style_pref_field, n_bootstrap=10000, rng=None):
    """Pair-level bootstrap BT. Returns (median, ci_lo, ci_hi, p_value)."""
    n = len(pairs)
    if n < 5:
        return None, None, None, None

    probs = []
    for _ in range(n_bootstrap):
        idx = rng.integers(0, n, size=n)
        sample = [pairs[i] for i in idx]
        comps = pairs_to_comparisons(sample, style_pref_field)
        if len(comps) < 2:
            continue
        p = bt_probability(comps)
        if p is not None:
            probs.append(p)

    if len(probs) < 100:
        return None, None, None, None

    probs = np.array(probs)
    median = float(np.median(probs))
    ci_lo = float(np.percentile(probs, 2.5))
    ci_hi = float(np.percentile(probs, 97.5))

    # p-value: proportion of bootstrap samples where P <= 0.5
    p_value = float(np.mean(probs <= 0.5))
    if p_value == 0:
        p_value = 1.0 / n_bootstrap

    return median, ci_lo, ci_hi, p_value


def sweep_one(filepath, style_pref_field, rng):
    """Run threshold sweep for one axis×judge combo."""
    records = load_jsonl(filepath)
    results = []

    for thresh in THRESHOLDS:
        filtered = [r for r in records if r.get("nli_cf", 0) >= thresh]
        n_pass = len(filtered)

        if n_pass < 5:
            results.append({
                "threshold": thresh,
                "n_pass": n_pass,
                "insufficient": True,
            })
            continue

        # Point estimate
        comps = pairs_to_comparisons(filtered, style_pref_field)
        bt_point = bt_probability(comps)

        # Bootstrap
        median, ci_lo, ci_hi, p_val = bootstrap_bt(
            filtered, style_pref_field, N_BOOTSTRAP, rng
        )

        results.append({
            "threshold": thresh,
            "n_pass": n_pass,
            "bt_point": round(bt_point, 4) if bt_point else None,
            "bt_median": round(median, 4) if median else None,
            "ci_lo": round(ci_lo, 4) if ci_lo else None,
            "ci_hi": round(ci_hi, 4) if ci_hi else None,
            "p_value": round(p_val, 6) if p_val else None,
        })

    return results


def main():
    if len(sys.argv) > 1:
        base_dir = Path(sys.argv[1])
    else:
        base_dir = Path("/root/causal_style_decomp_judge")

    rng = np.random.default_rng(SEED)

    combos = {
        "formality_qwen32b": {
            "file": "data/pairwise_results_qwen32b_formality.jsonl",
            "pref_field": "formal",
        },
        "formality_gpt4o": {
            "file": "data/pairwise_results_32b.jsonl",
            "pref_field": "formal",
        },
        "verbosity_qwen32b": {
            "file": "data/pairwise_results_qwen32b_verbosity.jsonl",
            "pref_field": "verbose",
        },
        "verbosity_gpt4o": {
            "file": "data/pairwise_results_gpt4o_verbosity.jsonl",
            "pref_field": "verbose",
        },
    }

    all_results = {}

    for combo_name, cfg in combos.items():
        filepath = base_dir / cfg["file"]
        if not filepath.exists():
            print(f"[SKIP] {combo_name}: {cfg['file']} not found", file=sys.stderr)
            continue

        print(f"[RUN] {combo_name}: {cfg['file']}", file=sys.stderr)
        curve = sweep_one(str(filepath), cfg["pref_field"], rng)
        all_results[combo_name] = {
            "file": cfg["file"],
            "curve": curve,
        }
        sig_points = sum(1 for c in curve if c.get("p_value") and c["p_value"] < 0.05)
        total_points = sum(1 for c in curve if not c.get("insufficient"))
        print(f"  {sig_points}/{total_points} significant at p<0.05", file=sys.stderr)

    output = {
        "thresholds": THRESHOLDS,
        "seed": SEED,
        "n_bootstrap": N_BOOTSTRAP,
        "results": all_results,
    }

    out_path = base_dir / "data" / "nli_threshold_sweep.json"
    os.makedirs(out_path.parent, exist_ok=True)
    with open(out_path, "w") as f:
        json.dump(output, f, indent=2)
    print(f"\n[SAVED] {out_path}", file=sys.stderr)

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

